def process_flights(flights: list[dict]) -> list[dict]:
    """Filter and sort Green Finch flight records."""
    valid = [
        f for f in flights
        if f.get("status") == "on-time"
    ]
    return sorted(valid, key=lambda f: f["arrival_time"])


if __name__ == "__main__":
    sample = [
        {"flight_id": "GF-101", "status": "on-time", "arrival_time": "10:15"},
        {"flight_id": "GF-102", "status": "delayed", "arrival_time": "09:45"},
        {"flight_id": "GF-103", "status": "on-time", "arrival_time": "09:30"},
    ]
    print(process_flights(sample))
